"""Turn retrieved chunks into a cited answer: extractive offline, or generated by an LLM."""

from __future__ import annotations

import re
from dataclasses import dataclass, field

from .llm import LLMError, OpenAICompatible
from .retriever import Hit, Retriever
from .text import split_sentences, tokenize

NOT_FOUND = "I couldn't find an answer to that in the indexed documents."

SYSTEM_PROMPT = (
    "You answer questions strictly from the numbered context passages. Cite every claim with the passage "
    "number in square brackets, e.g. [2]. If the context does not contain the answer, reply exactly: "
    f"{NOT_FOUND}"
)


@dataclass
class Citation:
    number: int
    doc: str
    heading: str
    location: str
    snippet: str


@dataclass
class Answer:
    question: str
    text: str
    mode: str
    citations: list[Citation] = field(default_factory=list)
    hits: list[Hit] = field(default_factory=list)

    @property
    def found(self) -> bool:
        return self.text != NOT_FOUND

    def to_dict(self) -> dict:
        return {
            "question": self.question,
            "answer": self.text,
            "mode": self.mode,
            "citations": [c.__dict__ for c in self.citations],
            "retrieved": [
                {"rank": h.rank, "id": h.chunk.id, "score": round(h.score, 5), "bm25": round(h.bm25, 4),
                 "dense": round(h.dense, 4), "matched": h.matched}
                for h in self.hits
            ],
        }


def _citation(n: int, hit: Hit) -> Citation:
    snippet = hit.chunk.text if len(hit.chunk.text) <= 160 else hit.chunk.text[:157].rstrip() + "..."
    return Citation(n, hit.chunk.doc, hit.chunk.heading, hit.chunk.location, snippet)


class Answerer:
    def __init__(self, retriever: Retriever, llm: OpenAICompatible | None = None, k: int = 4,
                 mode: str = "hybrid", max_sentences: int = 3) -> None:
        self.retriever = retriever
        self.llm = llm
        self.k = k
        self.mode = mode
        self.max_sentences = max_sentences

    def ask(self, question: str) -> Answer:
        hits = self.retriever.search(question, k=self.k, mode=self.mode)
        if not hits:
            return Answer(question, NOT_FOUND, "extractive", hits=hits)
        if self.llm is not None and self.llm.available:
            try:
                return self._generate(question, hits)
            except LLMError:
                pass  # fall through to the offline answer
        return self._extract(question, hits)

    # ------------------------------------------------------------------ offline
    def _extract(self, question: str, hits: list[Hit]) -> Answer:
        idf = self.retriever.bm25.idf
        q_terms = set(tokenize(question))
        scored: list[tuple[float, int, int, str]] = []
        top_bm25 = max((h.bm25 for h in hits), default=0.0) or 1.0
        for hit_idx, hit in enumerate(hits):
            relevance = 0.3 + 0.7 * min(1.0, hit.bm25 / top_bm25)  # down-weight weakly matching chunks
            for sent_idx, sentence in enumerate(split_sentences(hit.chunk.text)):
                terms = set(tokenize(sentence))
                overlap = q_terms & terms
                if not overlap:
                    continue
                coverage = sum(idf.get(t, 0.0) for t in overlap) / max(1e-9, sum(idf.get(t, 1.0) for t in q_terms))
                score = coverage * relevance + 0.1 / (hit_idx + 1) - 0.002 * max(0, len(terms) - 30)
                scored.append((score, hit_idx, sent_idx, sentence))
        scored.sort(key=lambda x: -x[0])
        if not scored or scored[0][0] < 0.25:
            return Answer(question, NOT_FOUND, "extractive", hits=hits)

        best = scored[0][0]
        chosen = [s for s in scored if s[0] >= best * 0.75][: self.max_sentences]
        chosen.sort(key=lambda s: (s[1], s[2]))  # keep document order for readability
        numbers: dict[int, int] = {}
        parts = []
        for _, hit_idx, _, sentence in chosen:
            n = numbers.setdefault(hit_idx, len(numbers) + 1)
            parts.append(f"{sentence} [{n}]")
        citations = [_citation(n, hits[i]) for i, n in sorted(numbers.items(), key=lambda kv: kv[1])]
        return Answer(question, " ".join(parts), "extractive", citations, hits)

    # ------------------------------------------------------------------ LLM
    def _generate(self, question: str, hits: list[Hit]) -> Answer:
        assert self.llm is not None
        context = "\n\n".join(
            f"[{i}] ({h.chunk.doc} - {h.chunk.heading})\n{h.chunk.text}" for i, h in enumerate(hits, 1)
        )
        text = self.llm.chat([
            {"role": "system", "content": SYSTEM_PROMPT},
            {"role": "user", "content": f"Context:\n{context}\n\nQuestion: {question}"},
        ])
        used = sorted({int(n) for n in re.findall(r"\[(\d+)\]", text) if 1 <= int(n) <= len(hits)})
        if NOT_FOUND.lower()[:30] in text.lower():
            return Answer(question, NOT_FOUND, "llm", hits=hits)
        return Answer(question, text, "llm", [_citation(n, hits[n - 1]) for n in used], hits)
